16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
41	    private static final Map<String, String> CITY_REGION = Map.of(
42	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
43	
44	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
45	     *  {@link #getLocality()} in preference to the city. */
46	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
47	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
48	
49	    @Column(name = "address")
50	    @NotEmpty
51	    private String address;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "membership_number")
82	    private String membershipNumber;
83	
84	    @Column(name = "bulk_signup_warning")
85	    private Boolean bulkSignupWarning;
86	
87	    @Column(name = "household_size")
88	    private Integer householdSize;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    /**
110	     * The owner's locality, i.e. the canonical region it belongs to (currently the
111	     * region derived from its own fields; see {@link #regionForOwner()}). Exposed as a
112	     * derived (not persisted) property and recomputed each call.
113	     *
114	     * @return the canonical region string, or {@code "UNKNOWN"}
115	     */
116	    @Transient
117	    public String getLocality() {
118	        return regionForOwner();
119	    }
120	
121	    /**
122	     * The canonical region derived for this owner from its own fields. The
123	     * {@link #postcode} is consulted first: when it is present and falls within a known
124	     * region's inclusive 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
125	     * {@code QLD 4000-4099}) that region is returned. Only when the postcode is absent
126	     * or in no known range does this fall back to the fixed city-to-region table
127	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
128	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
129	     * the same region for the known cities while disambiguating cities that share a name
130	     * via their postcode. Recomputed from the current fields each call.
131	     *
132	     * @return the canonical region string, or {@code "UNKNOWN"}
133	     */
134	    public String regionForOwner() {
135	        String byPostcode = regionForPostcode(this.postcode);
136	        if (byPostcode != null) {
137	            return byPostcode;
138	        }
139	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
140	    }
141	
142	    /**
143	     * The region whose inclusive postcode range contains the given postcode, or
144	     * {@code null} when the postcode is absent, not a four-digit number, or in no
145	     * known range.
146	     */
147	    private static String regionForPostcode(String postcode) {
148	        if (postcode == null || !postcode.matches("\\d{4}")) {
149	            return null;
150	        }
151	        int value = Integer.parseInt(postcode);
152	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
153	            int[] range = entry.getValue();
154	            if (value >= range[0] && value <= range[1]) {
155	                return entry.getKey();
156	            }
157	        }
158	        return null;
159	    }
160	
161	    /**
162	     * The owner's membership level, a number from 1 to 3 assigned at creation:
163	     * starting at 1, add 1 when an {@link #email} is present and add 1 when
164	     * {@link #namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
165	     * Derived (not persisted); recomputed from the current fields each call.
166	     *
167	     * @return the membership level, from 1 to 3
168	     */
169	    @Transient
170	    public Integer getMembershipLevel() {
171	        int level = 1;
172	        if (this.email != null && !this.email.isBlank()) {
173	            level++;
174	        }
175	        if (this.namesakeCount != null && this.namesakeCount == 0) {
176	            level++;
177	        }
178	        return Math.min(level, 3);
179	    }
180	
181	    /**
182	     * The owner's preferred contact channel: {@code "EMAIL"} when an
183	     * {@link #email} is present, otherwise {@code "PHONE"}. Derived (not
184	     * persisted); recomputed from the current fields each call.
185	     *
186	     * @return {@code "EMAIL"} or {@code "PHONE"}
187	     */
188	    @Transient
189	    public String getContactPreference() {
190	        if (this.email != null && !this.email.isBlank()) {
191	            return "EMAIL";
192	        }
193	        return "PHONE";
194	    }
195	
196	    public String getTelephone() {
197	        return this.telephone;
198	    }
199	
200	    public void setTelephone(String telephone) {
201	        this.telephone = telephone;
202	    }
203	
204	    public String getEmail() {
205	        return this.email;
206	    }
207	
208	    public void setEmail(String email) {
209	        this.email = email;
210	    }
211	
212	    public String getPostcode() {
213	        return this.postcode;
214	    }
215	
216	    public void setPostcode(String postcode) {
217	        this.postcode = postcode;
218	    }
219	
220	    public LocalDate getRegistrationDate() {
221	        return this.registrationDate;
222	    }
223	
224	    public void setRegistrationDate(LocalDate registrationDate) {
225	        this.registrationDate = registrationDate;
226	    }
227	
228	    public String getCustomerCode() {
229	        return this.customerCode;
230	    }
231	
232	    public void setCustomerCode(String customerCode) {
233	        this.customerCode = customerCode;
234	    }
235	
236	    /**
237	     * The Luhn check digit (0-9) computed over the decimal digits contained in this
238	     * owner's {@link #customerCode}. Derived (not persisted); recomputed from the
239	     * current customer code each call. An absent or digit-free customer code yields
240	     * {@code 0}.
241	     *
242	     * @return the Luhn check digit, from 0 to 9
243	     */
244	    @Transient
245	    public Integer getCheckDigit() {
246	        return luhnCheckDigit(this.customerCode);
247	    }
248	
249	    /**
250	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
251	     * given value, processed right-to-left with every second digit doubled (and
252	     * reduced by 9 when the double exceeds 9). Non-digit characters are ignored, and
253	     * an absent or digit-free value yields {@code 0}.
254	     */
255	    private static int luhnCheckDigit(String value) {
256	        int sum = 0;
257	        boolean doubleDigit = true;
258	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
259	            char c = value.charAt(i);
260	            if (c < '0' || c > '9') {
261	                continue;
262	            }
263	            int d = c - '0';
264	            if (doubleDigit) {
265	                d *= 2;
266	                if (d > 9) {
267	                    d -= 9;
268	                }
269	            }
270	            sum += d;
271	            doubleDigit = !doubleDigit;
272	        }
273	        return (10 - (sum % 10)) % 10;
274	    }
275	
276	    public String getHouseholdId() {
277	        return this.householdId;
278	    }
279	
280	    public void setHouseholdId(String householdId) {
281	        this.householdId = householdId;
282	    }
283	
284	    public Integer getNamesakeCount() {
285	        return this.namesakeCount;
286	    }
287	
288	    public void setNamesakeCount(Integer namesakeCount) {
289	        this.namesakeCount = namesakeCount;
290	    }
291	
292	    public String getMembershipNumber() {
293	        return this.membershipNumber;
294	    }
295	
296	    public void setMembershipNumber(String membershipNumber) {
297	        this.membershipNumber = membershipNumber;
298	    }
299	
300	    public Boolean getBulkSignupWarning() {
301	        return this.bulkSignupWarning;
302	    }
303	
304	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
305	        this.bulkSignupWarning = bulkSignupWarning;
306	    }
307	
308	    public Integer getHouseholdSize() {
309	        return this.householdSize;
310	    }
311	
312	    public void setHouseholdSize(Integer householdSize) {
313	        this.householdSize = householdSize;
314	    }
315	
316	    /**
317	     * The single derived key used for duplicate detection, formed as
318	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
319	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
320	     * is the stored (lower-cased) email or the empty string when absent, and the
321	     * household component is the stored {@link #householdId} or the empty string
322	     * when the owner belongs to no household. Two owners are duplicates of each
323	     * other exactly when their whole identity keys are equal; because the telephone
324	     * is part of the key, two members of the same household with different
325	     * telephones have different identity keys. Derived (not persisted); recomputed
326	     * from the current fields each call.
327	     *
328	     * @return the owner's identity key
329	     */
330	    @Transient
331	    public String getIdentityKey() {
332	        String tel = this.telephone == null ? "" : this.telephone;
333	        String mail = this.email == null ? "" : this.email;
334	        String household = this.householdId == null ? "" : this.householdId;
335	        return tel + "|" + mail + "|" + household;
336	    }
337	
338	    /**
339	     * A stable, normalised key identifying this owner's household (same last name
340	     * and address). The last name is folded case- and whitespace-insensitively and
341	     * the address is reduced to its canonical form exactly as in
342	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
343	     * household.
344	     *
345	     * @return the household key
346	     */
347	    public String householdKey() {
348	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
349	    }
350	
351	    /**
352	     * Whether this owner belongs to the same household as {@code other}: that is,
353	     * they share the same last name and address. The last name is compared
354	     * case-insensitively with runs of whitespace collapsed to a single space (and
355	     * surrounding whitespace trimmed); the address is compared in its canonical
356	     * normalised form (see {@link #normalizeAddress(String)}).
357	     *
358	     * @param other the owner to compare against
359	     * @return {@code true} if both owners share a household
360	     */
361	    public boolean sameHouseholdAs(Owner other) {
362	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
363	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
364	    }
365	
366	    /**
367	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
368	     * trim, collapse internal runs of whitespace to a single space and lower-case.
369	     */
370	    private static String normalize(String value) {
371	        if (value == null) {
372	            return "";
373	        }
374	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
375	    }
376	
377	    /**
378	     * Reduce an address to its canonical stored form: trim and collapse runs of
379	     * whitespace to a single space, upper-case, and expand common abbreviations
380	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
381	     * they appear as whole words. The result is what is stored, returned and used
382	     * for every household comparison; it is idempotent, so re-normalising an
383	     * already-normalised address leaves it unchanged.
384	     *
385	     * @param value the raw address (may be {@code null})
386	     * @return the normalised address, or the empty string if {@code value} is
387	     *         {@code null} or blank
388	     */
389	    public static String normalizeAddress(String value) {
390	        if (value == null) {
391	            return "";
392	        }
393	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
394	        if (collapsed.isEmpty()) {
395	            return "";
396	        }
397	        String[] tokens = collapsed.split(" ");
398	        for (int i = 0; i < tokens.length; i++) {
399	            tokens[i] = switch (tokens[i]) {
400	                case "ST" -> "STREET";
401	                case "RD" -> "ROAD";
402	                case "AVE" -> "AVENUE";
403	                default -> tokens[i];
404	            };
405	        }
406	        return String.join(" ", tokens);
407	    }
408	
409	    protected Set<Pet> getPetsInternal() {
410	        if (this.pets == null) {
411	            this.pets = new HashSet<>();
412	        }
413	        return this.pets;
414	    }
415	
416	    protected void setPetsInternal(Set<Pet> pets) {
417	        this.pets = pets;
418	    }
419	
420	    public List<Pet> getPets() {
421	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
422	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
423	        return Collections.unmodifiableList(sortedPets);
424	    }
425	
426	    public void setPets(List<Pet> pets) {
427	        this.pets = new HashSet<>(pets);
428	    }
429	
430	    public void addPet(Pet pet) {
431	        getPetsInternal().add(pet);
432	        pet.setOwner(this);
433	    }
434	
435	    /**
436	     * Return the Pet with the given name, or null if none found for this Owner.
437	     *
438	     * @param name to test
439	     * @return true if pet name is already in use
440	     */
441	    public Pet getPet(String name) {
442	        return getPet(name, false);
443	    }
444	
445	    /**
446	     * Return the Pet with the given name, or null if none found for this Owner.
447	     *
448	     * @param name to test
449	     * @return true if pet name is already in use
450	     */
451	    public Pet getPet(String name, boolean ignoreNew) {
452	        name = name.toLowerCase();
453	        for (Pet pet : getPetsInternal()) {
454	            if (!ignoreNew || !pet.isNew()) {
455	                String compName = pet.getName();
456	                compName = compName.toLowerCase();
457	                if (compName.equals(name)) {
458	                    return pet;
459	                }
460	            }
461	        }
462	        return null;
463	    }
464	
465	    public Pet getPet(Integer petId) {
466	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
467	    }
468	
469	    @Override
470	    public String toString() {
471	        return new ToStringCreator(this)
472	
473	            .append("id", this.getId())
474	            .append("new", this.isNew())
475	            .append("lastName", this.getLastName())
476	            .append("firstName", this.getFirstName())
477	            .append("address", this.address)
478	            .append("city", this.city)
479	            .append("telephone", this.telephone)
480	            .toString();
481	    }
482	}
