112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        if (!normalizeNewOwner(owner)) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (dailyLimitReached(owner.getRegistrationDate())) {
117	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
118	        }
119	        if (cityIsAtCapacity(owner.getCity())) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        Optional<Owner> householdMember = findHouseholdMember(owner);
123	        if (householdMember.isPresent() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
124	            joinHousehold(owner, householdMember.get());
125	        }
126	        if (identityKeyAlreadyUsed(owner)) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        owner.setCustomerCode(customerCode(owner));
130	        owner.setNamesakeCount(countNamesakes(owner));
131	        owner.setMembershipNumber(membershipNumber(owner));
132	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
133	        owner.setHouseholdSize(householdSize(owner));
134	        this.clinicService.saveOwner(owner);
135	        auditOwnerCreated(owner);
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
145	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
146	        if (currentOwner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
