236	
237	    /**
238	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
239	     * the canonical form each stored value must take: the address is trimmed,
240	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
241	     * telephone is converted to E.164, any email is lower-cased and a missing
242	     * registration date defaults to today. Field-level rejections are reported here
243	     * rather than inline in {@link #addOwner}, and normalisation runs before any
244	     * household comparison so those comparisons see the canonical values.
245	     *
246	     * @param owner the freshly-mapped owner to normalise
247	     * @return {@code true} if the fields are valid, or {@code false} if the address
248	     *         is blank after normalisation or the telephone cannot form a valid
249	     *         E.164 number, in which case the request must be rejected with
250	     *         {@code 400 Bad Request}
251	     */
252	    private boolean normalizeNewOwner(Owner owner) {
253	        String address = Owner.normalizeAddress(owner.getAddress());
254	        if (address.isEmpty()) {
255	            return false;
256	        }
257	        owner.setAddress(address);
258	        String telephone = toE164(owner.getTelephone());
259	        if (telephone == null) {
260	            return false;
261	        }
262	        owner.setTelephone(telephone);
263	        if (owner.getEmail() != null) {
264	            owner.setEmail(owner.getEmail().toLowerCase());
265	        }
266	        if (!postcodeValidForCity(owner)) {
267	            return false;
268	        }
269	        if (owner.getRegistrationDate() == null) {
270	            owner.setRegistrationDate(LocalDate.now());
271	        }
272	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
273	        return true;
274	    }
275	
276	    /** Region -> inclusive 4-digit postcode range {low, high}. */
277	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
278	        "NSW", new int[] {2000, 2099},
279	        "VIC", new int[] {3000, 3099},
280	        "QLD", new int[] {4000, 4099});
281	
282	    /**
283	     * Validate the owner's postcode when one is supplied. A postcode is optional: an
284	     * owner created without one is accepted. When present it must be exactly four
285	     * digits and, when the owner's city maps to a known region (see
286	     * {@link Owner#getLocality()}), fall within that region's inclusive postcode
287	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
288	     * region accepts any four-digit postcode.
289	     *
290	     * @param owner the freshly-mapped owner being created
291	     * @return {@code true} if the postcode is absent or valid, {@code false} if it is
292	     *         malformed or out of range for the city's region (reject with 400)
293	     */
294	    private static boolean postcodeValidForCity(Owner owner) {
295	        String postcode = owner.getPostcode();
296	        if (postcode == null) {
297	            return true;
298	        }
299	        if (!postcode.matches("\\d{4}")) {
300	            return false;
301	        }
302	        int[] range = REGION_POSTCODES.get(owner.getLocality());
303	        if (range == null) {
304	            return true;
305	        }
306	        int value = Integer.parseInt(postcode);
307	        return value >= range[0] && value <= range[1];
308	    }
309	
310	    /**
311	     * Roll the given date forward to the next business day when it falls on a
312	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
313	     * weekday is returned unchanged. Applied to the effective registration date
314	     * (whether supplied in the request or defaulted to the server date) so that
315	     * every value derived from it uses the adjusted business day.
316	     *
317	     * @param date the effective registration date
318	     * @return the same date if it is a weekday, otherwise the next Monday
319	     */
320	    private static LocalDate rollToBusinessDay(LocalDate date) {
321	        switch (date.getDayOfWeek()) {
322	            case SATURDAY:
323	                return date.plusDays(2);
324	            case SUNDAY:
325	                return date.plusDays(1);
326	            default:
327	                return date;
328	        }
329	    }
330	
331	    /**
332	     * Determine whether the candidate owner's identity key collides with any existing
333	     * owner's. This is the single, consolidated duplicate check: it subsumes the
334	     * former separate telephone, email and household checks by comparing the whole
335	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
336	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
337	     * that agree on some — but not all — of the key's parts (for example two members of
338	     * the same household with different telephones) are not duplicates. Evaluated after
339	     * normalisation and household resolution, so the candidate's key reflects its
340	     * canonical field values and any household it has joined.
341	     *
342	     * @param owner the candidate owner being created, after household resolution
343	     * @return {@code true} if an existing owner has the same identity key
344	     */
345	    private boolean identityKeyAlreadyUsed(Owner owner) {
346	        String identityKey = owner.getIdentityKey();
347	        return this.clinicService.findAllOwners().stream()
348	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
349	    }
350	
351	    /**
352	     * Find an existing owner that belongs to the same household as the given owner,
353	     * i.e. shares the same last name and address (compared case-insensitively with
354	     * runs of whitespace collapsed to a single space).
355	     *
356	     * @param owner the candidate owner being created
357	     * @return the matching existing owner, or empty if none exists
358	     */
359	    private Optional<Owner> findHouseholdMember(Owner owner) {
360	        return this.clinicService.findAllOwners().stream()
361	            .filter(existing -> existing.sameHouseholdAs(owner))
362	            .findFirst();
363	    }
364	
365	    /**
366	     * Assign the joining owner and an existing household member the same stable
367	     * household identifier. The identifier is derived deterministically from the
368	     * shared household key (last name + address, normalised), so every owner in a
369	     * household resolves to the same value; the existing member is updated when it
370	     * does not already carry it.
371	     *
372	     * @param owner    the owner being created
373	     * @param existing an existing owner in the same household
374	     */
375	    private void joinHousehold(Owner owner, Owner existing) {
376	        String householdId = UUID
377	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
378	        owner.setHouseholdId(householdId);
379	        if (!householdId.equals(existing.getHouseholdId())) {
380	            existing.setHouseholdId(householdId);
381	            this.clinicService.saveOwner(existing);
382	        }
383	    }
384	
385	    /**
386	     * Count how many owners belong to the given owner's household once this create
387	     * completes: the owners that already share its {@code householdId} plus the owner
388	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
389	     * so the household identifier (and any existing member updated to it) is already in
390	     * place. An owner that has not joined a household (no {@code householdId}) is a
391	     * household of one.
392	     *
393	     * @param owner the candidate owner being created, after household resolution
394	     * @return the household member count after this create (at least {@code 1})
395	     */
396	    private int householdSize(Owner owner) {
397	        String householdId = owner.getHouseholdId();
398	        if (householdId == null) {
399	            return 1;
400	        }
401	        long existing = this.clinicService.findAllOwners().stream()
402	            .filter(other -> householdId.equals(other.getHouseholdId()))
403	            .count();
404	        return (int) existing + 1;
405	    }
406	
407	    /**
408	     * Count the existing owners that share the given owner's first and last name,
409	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
410	     * before the new owner is saved, so the result reflects only owners that
411	     * already existed at creation time.
412	     *
413	     * @param owner the candidate owner being created
414	     * @return the number of existing namesakes
415	     */
416	    private int countNamesakes(Owner owner) {
417	        String firstName = normalizeName(owner.getFirstName());
418	        String lastName = normalizeName(owner.getLastName());
419	        return (int) this.clinicService.findAllOwners().stream()
420	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
421	                && normalizeName(existing.getLastName()).equals(lastName))
422	            .count();
423	    }
424	
425	    private static String normalizeName(String value) {
426	        return value == null ? "" : value.trim().toLowerCase();
427	    }
428	
429	    /**
430	     * Determine whether the given city has already reached its owner capacity, i.e.
431	     * it already contains 50 or more existing owners (compared case-insensitively
432	     * with surrounding whitespace trimmed). A new owner may not be created in a city
433	     * that is at capacity.
434	     *
435	     * @param city the candidate owner's city
436	     * @return {@code true} if the city already holds 50 or more owners
437	     */
438	    private boolean cityIsAtCapacity(String city) {
439	        String normalizedCity = normalizeName(city);
440	        long count = this.clinicService.findAllOwners().stream()
441	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
442	            .count();
443	        return count >= 50;
444	    }
445	
446	    /**
447	     * Determine whether the daily owner-creation limit has already been reached, i.e.
448	     * 100 or more owners already carry the given registration date. A new owner may
449	     * not be created once that day's cap is reached.
450	     *
451	     * @param registrationDate the registration date the new owner would be created with
452	     * @return {@code true} if 100 or more existing owners share that registration date
453	     */
454	    private boolean dailyLimitReached(LocalDate registrationDate) {
455	        long count = this.clinicService.findAllOwners().stream()
456	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
457	            .count();
458	        return count >= 100;
459	    }
460	
461	    /**
462	     * Determine whether more than 80 owners have already been created for the given
463	     * registration date, i.e. strictly more than 80 existing owners carry that date.
464	     * Evaluated before the new owner is saved, so it reflects only owners that
465	     * already existed at creation time.
466	     *
467	     * @param registrationDate the registration date the new owner would be created with
468	     * @return {@code true} if more than 80 existing owners share that registration date
469	     */
470	    private boolean bulkSignupWarning(LocalDate registrationDate) {
471	        long count = this.clinicService.findAllOwners().stream()
472	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
473	            .count();
474	        return count > 80;
475	    }
476	
477	    /**
478	     * Build the customer code assigned to the given owner, formatted
479	     * {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three letters of
480	     * the owner's city, LAST3 the upper-cased first three letters of its last name and
481	     * NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
482	     * owners already in that city (e.g. {@code SYD-SMI-0007}). The whole owner is passed
483	     * so the code can be derived from whichever of its (already normalised) fields the
484	     * identity scheme requires.
485	     *
486	     * @param owner the owner being created, with its fields already normalised
487	     * @return the assigned customer code
488	     */
489	    private String customerCode(Owner owner) {
490	        String city3 = prefix3(owner.getCity());
491	        String last3 = prefix3(owner.getLastName());
492	        long sequence = this.clinicService.findAllOwners().stream()
493	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(owner.getCity())))
494	            .count() + 1L;
495	        return String.format("%s-%s-%04d", city3, last3, sequence);
496	    }
497	
498	    private static String prefix3(String value) {
499	        String v = value == null ? "" : value;
500	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
501	    }
502	
503	    /**
504	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
505	     * one place so it stays in step with the owner's identity: it reports the assigned
506	     * customer code alongside the owner's id, registration date and membership level.
507	     *
508	     * @param owner the owner that has just been created and saved
509	     */
510	    private void auditOwnerCreated(Owner owner) {
511	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
512	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
513	    }
514	
515	    /**
516	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
517	     * where {@code <customerCode>} is the owner's already-assigned customer code and
518	     * YY is the last two digits of the registration date's year (e.g.
519	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
520	     * have been set.
521	     *
522	     * @param owner the owner being created, with customer code and registration date
523	     *              already assigned
524	     * @return the assigned membership number
525	     */
526	    private String membershipNumber(Owner owner) {
527	        int yy = owner.getRegistrationDate().getYear() % 100;
528	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
529	    }
530	
531	    /**
532	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
533	     * code when present, otherwise assume country code '+61' and drop a single
534	     * leading '0' from the national digits. Spaces, dashes and brackets are
535	     * stripped. The result must contain 8 to 15 digits after the '+'.
536	     *
537	     * <p>In addition, the national-number length is validated against the country
538	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
539	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
540	     * whose national-number length is wrong for its country code is rejected.
541	     *
542	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
543	     *         input cannot form a valid E.164 number.
544	     */
545	    private static String toE164(String raw) {
546	        if (raw == null) {
547	            return null;
548	        }
549	        String cleaned = raw.replaceAll("[\\s()-]", "");
550	        String digits;
551	        if (cleaned.startsWith("+")) {
552	            digits = cleaned.substring(1);
553	        } else {
554	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
555	            digits = "61" + national;
556	        }
557	        if (!digits.matches("\\d{8,15}")) {
558	            return null;
559	        }
560	        if (!nationalNumberLengthValid(digits)) {
561	            return null;
562	        }
563	        return "+" + digits;
564	    }
565	
566	    /**
567	     * Validate the length of the national number (the digits after the country
568	     * code) against the country code carried by the given E.164 digit string: a
569	     * {@code 61} (Australia) number requires exactly 9 national digits and a
570	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
571	     * without a pinned length are accepted (only the generic 8-15 digit rule
572	     * applies to them).
573	     *
574	     * @param digits the E.164 digits without the leading '+'
575	     * @return {@code true} if the national-number length is correct for the country
576	     */
577	    private static boolean nationalNumberLengthValid(String digits) {
578	        if (digits.startsWith("61")) {
579	            return digits.length() - 2 == 9;
580	        }
581	        if (digits.startsWith("1")) {
582	            return digits.length() - 1 == 10;
583	        }
584	        return true;
585	    }
586	}
